  static const FieldDecl *getCounterFieldFromFAM(const FieldDecl *FAMFD);
  static bool isAssignmentToCounterField(const FieldRegion *FR,
                                         const FieldDecl *&CounterFD,
                                         const FieldDecl *&FAMFD);

  // Outcome of comparing a copy size against the recorded counter value.
  enum class CapacityRelation { Safe, Violates, Unknown };
  static CapacityRelation compareWithCounterCapacity(CheckerContext &C,
                                                     SVal SizeVal,
