bool SAGenTestChecker::isArrayAwareAllocator(const CallEvent &Call) const {
  const IdentifierInfo *ID = Call.getCalleeIdentifier();
  if (!ID)
    return false;

  StringRef Name = ID->getName();
  return Name == "kcalloc" || Name == "kvcalloc" ||
         Name == "kmalloc_array" || Name == "kvmalloc_array" ||
         Name == "devm_kcalloc";
}

bool SAGenTestChecker::getAllocatorSizeArgIndex(const CallEvent &Call,
                                                unsigned &Idx,
                                                StringRef &AllocatorName) const {
  const IdentifierInfo *ID = Call.getCalleeIdentifier();
  if (!ID)
    return false;

  AllocatorName = ID->getName();

  // Order is explicit to keep the argument positions easy to audit.
  if (AllocatorName == "devm_kzalloc" ||
      AllocatorName == "devm_kmalloc") {
    Idx = 1;
    return true;
  }

  if (AllocatorName == "kvzalloc" || AllocatorName == "kvmalloc" ||
      AllocatorName == "kzalloc" || AllocatorName == "kmalloc" ||
      AllocatorName == "vzalloc") {
    Idx = 0;
    return true;
  }

  return false;
}

