// This check is deliberately limited to kvzalloc. It suppresses the reported
// KFD case when an unsigned count multiplied by sizeof is provably representable
// on the current target. Other allocator patterns, including the target kzalloc
// case, retain the checker's existing behavior.
bool SAGenTestChecker::isUnsignedProductRepresentable(
    const BinaryOperator *Mul, const Expr *CountExpr,
    const UnaryExprOrTypeTraitExpr *SizeofExpr, CheckerContext &C) {
  if (!Mul || !CountExpr || !SizeofExpr)
    return false;

  ASTContext &Ctx = C.getASTContext();
  QualType CountType = CountExpr->getType();
  QualType ResultType = Mul->getType();

  if (CountType.isNull() || ResultType.isNull() ||
      !CountType->isUnsignedIntegerType() ||
      !ResultType->isUnsignedIntegerType())
    return false;

  Expr::EvalResult SizeResult;
  if (!SizeofExpr->EvaluateAsInt(SizeResult, Ctx))
    return false;

  llvm::APSInt SizeValue = SizeResult.Val.getInt();
  if (SizeValue.isNegative())
    return false;

  const unsigned CountWidth = Ctx.getIntWidth(CountType);
  const unsigned ResultWidth = Ctx.getIntWidth(ResultType);
  if (CountWidth == 0 || ResultWidth == 0 || CountWidth > ResultWidth)
    return false;

  llvm::APInt MaxCount = llvm::APInt::getMaxValue(CountWidth);
  MaxCount = MaxCount.zextOrTrunc(ResultWidth);

  llvm::APInt ElementSize = SizeValue;
  ElementSize = ElementSize.zextOrTrunc(ResultWidth);

  llvm::APInt Product(ResultWidth, 0);
  return !MaxCount.umul_ov(ElementSize, Product);
}

void SAGenTestChecker::reportMulPattern(const BinaryOperator *Mul,
                                        CheckerContext &C) const {
  if (!Mul)
    return;

  ExplodedNode *N = C.generateNonFatalErrorNode();
  if (!N)
    return;

  auto R = std::make_unique<PathSensitiveBugReport>(
      *BT,
      "Use kcalloc(count, size, ...) instead of count*sizeof in allocation "
      "to avoid integer overflow",
      N);
  R->addRange(Mul->getSourceRange());
  C.emitReport(std::move(R));
}

void SAGenTestChecker::checkPreCall(const CallEvent &Call,
                                    CheckerContext &C) const {
  if (isArrayAwareAllocator(Call))
    return;

  unsigned SizeIdx = 0;
  StringRef AllocatorName;
  if (!getAllocatorSizeArgIndex(Call, SizeIdx, AllocatorName))
    return;

  if (Call.getNumArgs() <= SizeIdx)
    return;

  const Expr *SizeE = Call.getArgExpr(SizeIdx);
  if (!SizeE)
    return;

  // Suppress known overflow-safe size helpers.
  if (ExprHasName(SizeE, "array_size", C) ||
      ExprHasName(SizeE, "struct_size", C) ||
      ExprHasName(SizeE, "flex_array_size", C))
    return;

  SizeE = SizeE->IgnoreParenImpCasts();
  const auto *Mul = dyn_cast<BinaryOperator>(SizeE);
  if (!Mul || Mul->getOpcode() != BO_Mul)
    return;

  const Expr *LHS = Mul->getLHS()->IgnoreParenImpCasts();
  const Expr *RHS = Mul->getRHS()->IgnoreParenImpCasts();

  const UnaryExprOrTypeTraitExpr *LHSSizeof = findSizeof(LHS);
  const UnaryExprOrTypeTraitExpr *RHSSizeof = findSizeof(RHS);
  if (!LHSSizeof && !RHSSizeof)
    return;

  // For kvzalloc, suppress a report only when the unsigned count's full type
  // range multiplied by sizeof is proven to fit the multiplication result.
  // If evaluation or type reasoning is inconclusive, keep the diagnostic.
  if (AllocatorName == "kvzalloc") {
    const Expr *CountExpr = LHSSizeof ? RHS : LHS;
    const UnaryExprOrTypeTraitExpr *SizeofExpr =
        LHSSizeof ? LHSSizeof : RHSSizeof;

    if (isUnsignedProductRepresentable(Mul, CountExpr, SizeofExpr, C))
      return;
  }

  reportMulPattern(Mul, C);
}

