using namespace taint;

namespace {
class SAGenTestChecker : public Checker<check::PreCall> {
  mutable std::unique_ptr<BugType> BT;

public:
  SAGenTestChecker()
      : BT(new BugType(this, "Overflow-prone allocation size (use kcalloc)",
                       "API Misuse")) {}

  void checkPreCall(const CallEvent &Call, CheckerContext &C) const;

private:
  bool isArrayAwareAllocator(const CallEvent &Call) const;
  bool getAllocatorSizeArgIndex(const CallEvent &Call, unsigned &Idx) const;
  static const UnaryExprOrTypeTraitExpr *findSizeof(const Expr *E);
  static bool isMemberBasedCount(const Expr *E);
  static bool countCannotOverflowSizeT(const Expr *Count,
                                       const UnaryExprOrTypeTraitExpr *Sizeof,
                                       CheckerContext &C);
  void reportMulPattern(const BinaryOperator *Mul, CheckerContext &C) const;
};

bool SAGenTestChecker::isArrayAwareAllocator(const CallEvent &Call) const {
  const IdentifierInfo *ID = Call.getCalleeIdentifier();
  if (!ID)
    return false;

  StringRef Name = ID->getName();
  return Name == "kcalloc" || Name == "kvcalloc" ||
         Name == "kmalloc_array" || Name == "kvmalloc_array" ||
         Name == "devm_kcalloc";
}

bool SAGenTestChecker::getAllocatorSizeArgIndex(const CallEvent &Call,
                                                unsigned &Idx) const {
  const IdentifierInfo *ID = Call.getCalleeIdentifier();
  if (!ID)
    return false;

  StringRef Name = ID->getName();

  struct Entry {
    StringLiteral Name;
    unsigned SizeIdx;
  };

  static const Entry Targets[] = {
      {"devm_kzalloc", 1},
      {"devm_kmalloc", 1},
      {"kvzalloc", 0},
      {"kvmalloc", 0},
      {"kzalloc", 0},
      {"kmalloc", 0},
      {"vzalloc", 0},
  };

  for (const Entry &E : Targets) {
    if (Name == E.Name) {
      Idx = E.SizeIdx;
      return true;
    }
  }

  return false;
}

const UnaryExprOrTypeTraitExpr *
SAGenTestChecker::findSizeof(const Expr *E) {
  if (!E)
    return nullptr;

  const auto *UETT =
      findSpecificTypeInChildren<UnaryExprOrTypeTraitExpr>(E);
  if (!UETT || UETT->getKind() != UETT_SizeOf)
    return nullptr;

  return UETT;
}

bool SAGenTestChecker::isMemberBasedCount(const Expr *E) {
  if (!E)
    return false;

  E = E->IgnoreParenImpCasts();
  return isa<MemberExpr>(E);
}

bool SAGenTestChecker::countCannotOverflowSizeT(
    const Expr *Count, const UnaryExprOrTypeTraitExpr *Sizeof,
    CheckerContext &C) {
  if (!Count || !Sizeof)
    return false;

  Count = Count->IgnoreParenImpCasts();
  QualType CountType = Count->getType();
  if (!CountType->isIntegerType() || CountType->isSignedIntegerType())
    return false;

  llvm::APSInt ElementSize;
  if (!EvaluateExprToInt(ElementSize, Sizeof, C) ||
      ElementSize.isNegative() || ElementSize == 0)
    return false;

  ASTContext &Ctx = C.getASTContext();
  unsigned SizeTWidth = Ctx.getTypeSize(Ctx.getSizeType());
  unsigned CountWidth = Ctx.getTypeSize(CountType);

  // This check only suppresses cases where the count's full type range,
  // multiplied by sizeof's constant value, fits in size_t.
  if (CountWidth >= SizeTWidth)
    return false;

  llvm::APInt MaxCount(CountWidth, 0);
  MaxCount.setAllBits();

  llvm::APInt MaxSizeT(SizeTWidth, 0);
  MaxSizeT.setAllBits();

  llvm::APInt ElementSizeValue =
      ElementSize.getValue().zextOrTrunc(SizeTWidth);
  if (ElementSizeValue.isZero())
    return false;

  return MaxCount.ule(MaxSizeT.udiv(ElementSizeValue));
}

void SAGenTestChecker::reportMulPattern(const BinaryOperator *Mul,
                                        CheckerContext &C) const {
  if (!Mul)
    return;

  ExplodedNode *N = C.generateNonFatalErrorNode();
  if (!N)
    return;

  auto R = std::make_unique<PathSensitiveBugReport>(
      *BT,
      "Use kcalloc(count, size, ...) instead of count*sizeof in allocation "
      "to avoid integer overflow",
      N);
  R->addRange(Mul->getSourceRange());
  C.emitReport(std::move(R));
}

void SAGenTestChecker::checkPreCall(const CallEvent &Call,
                                    CheckerContext &C) const {
  if (isArrayAwareAllocator(Call))
    return;

  unsigned SizeIdx = 0;
  if (!getAllocatorSizeArgIndex(Call, SizeIdx) ||
      Call.getNumArgs() <= SizeIdx)
    return;

  const Expr *SizeE = Call.getArgExpr(SizeIdx);
  if (!SizeE)
    return;

  // These helpers perform checked size calculations themselves.
  if (ExprHasName(SizeE, "array_size", C) ||
      ExprHasName(SizeE, "struct_size", C) ||
      ExprHasName(SizeE, "flex_array_size", C))
    return;

  SizeE = SizeE->IgnoreParenImpCasts();
  const auto *Mul = dyn_cast<BinaryOperator>(SizeE);
  if (!Mul || Mul->getOpcode() != BO_Mul)
    return;

  const Expr *LHS = Mul->getLHS()->IgnoreParenImpCasts();
  const Expr *RHS = Mul->getRHS()->IgnoreParenImpCasts();

  const UnaryExprOrTypeTraitExpr *LSizeof = findSizeof(LHS);
  const UnaryExprOrTypeTraitExpr *RSizeof = findSizeof(RHS);
  if (!LSizeof && !RSizeof)
    return;

  const Expr *Count = LSizeof ? RHS : LHS;
  const UnaryExprOrTypeTraitExpr *Sizeof = LSizeof ? LSizeof : RSizeof;

  // A member-based count can be externally supplied (as in
  // args->num_of_nodes), so retain the warning even when its declared type
  // alone would bound its maximum below SIZE_MAX.
  if (!isMemberBasedCount(Count) &&
      countCannotOverflowSizeT(Count, Sizeof, C))
    return;

  reportMulPattern(Mul, C);
}

} // namespace

