void SAGenTestChecker::checkBranchCondition(const Stmt *Condition, CheckerContext &C) const {
  if (!Condition)
    return;

  // Find the IfStmt that owns this condition.
  const IfStmt *IS = findSpecificTypeInParents<IfStmt>(Condition, C);
  if (!IS)
    return;

  const Stmt *Then = IS->getThen();
  if (!Then)
    return;

  ProgramStateRef State = C.getState();

  // The then-branch of a direct null-failure test cannot leak the allocation:
  // the allocator returned null on that path, so there is no device to free.
  if (thenBranchIsNullFailure(Condition, State, C))
    return;

  // Does the then-branch contain a goto to an "exit-like" label?
  GotoCollectorVisitor GV;
  GV.TraverseStmt(const_cast<Stmt *>(Then));

  bool HasExitLikeGoto = false;
  for (const GotoStmt *GS : GV.Gotos) {
    if (!GS) continue;
    const LabelDecl *LD = GS->getLabel();
    if (isExitLikeLabel(LD)) {
      HasExitLikeGoto = true;
      break;
    }
  }
  if (!HasExitLikeGoto)
    return;

  // Find enclosing loop of this if-statement.
  const Stmt *LoopS = findEnclosingLoop(IS, C);
  if (!LoopS)
    return;

  auto Pend = State->get<PendingNetdevMap>();
  if (Pend.isEmpty())
    return;

  // For each pending netdev tied to this loop, ensure Then frees it before goto.
  for (auto I = Pend.begin(), E = Pend.end(); I != E; ++I) {
    const MemRegion *R = I->first;
    if (!R) continue;
    R = R->getBaseRegion();

    auto RLoop = State->get<NetdevLoopMap>(R);
    if (!RLoop || *RLoop != LoopS)
      continue;

    // Check whether Then frees the current iteration's net_device.
    if (!thenContainsFreeOfRegion(Then, State, R, C)) {
      ExplodedNode *N = C.generateNonFatalErrorNode();
      if (!N)
        return;

      auto Rpt = std::make_unique<PathSensitiveBugReport>(
          *BT, "Missing free_netdev before goto exit; leaks current net_device",
          N);
      // Try to highlight the 'then' branch range.
      Rpt->addRange(Then->getSourceRange());
      C.emitReport(std::move(Rpt));
      // Do not break; potentially multiple regions (though uncommon).
    }
  }
}

// Return true if E refers to a currently tracked netdev allocation.
bool SAGenTestChecker::isTrackedNetdevExpr(const Expr *E,
                                            ProgramStateRef State,
                                            CheckerContext &C) {
  if (!E)
    return false;

  const MemRegion *R = getMemRegionFromExpr(E, C);
  if (!R)
    return false;

  R = canonicalizeRegion(State, R->getBaseRegion());
  if (!R)
    return false;

  auto Pending = State->get<PendingNetdevMap>();
  for (auto I = Pending.begin(), End = Pending.end(); I != End; ++I) {
    const MemRegion *TrackedR = canonicalizeRegion(State, I->first);
    if (TrackedR && TrackedR == R)
      return true;
  }

  return false;
}

// Recognize integer zero and nullptr as null pointer constants.
bool SAGenTestChecker::isNullConstant(const Expr *E, CheckerContext &C) {
  if (!E)
    return false;

  E = E->IgnoreParenImpCasts();
  if (isa<CXXNullPtrLiteralExpr>(E))
    return true;

  llvm::APSInt Value;
  return EvaluateExprToInt(Value, E, C) && Value == 0;
}

// Return:
//   1 if a true condition means the tracked pointer is null,
//   0 if a false condition means the tracked pointer is null,
//  -1 if this is not a recognized null test.
int SAGenTestChecker::nullTestTrueMeansNull(const Expr *E,
                                            ProgramStateRef State,
                                            CheckerContext &C) {
  if (!E)
    return -1;

  E = E->IgnoreParenImpCasts();

  if (const auto *UO = dyn_cast<UnaryOperator>(E)) {
    if (UO->getOpcode() == UO_LNot) {
      const Expr *SubExpr = UO->getSubExpr()->IgnoreParenImpCasts();

      // In C, a pointer used as a condition is false exactly when it is null.
      if (isTrackedNetdevExpr(SubExpr, State, C))
        return 1;

      int Polarity = nullTestTrueMeansNull(SubExpr, State, C);
      if (Polarity != -1)
        return 1 - Polarity;
    }
  }

  if (const auto *BO = dyn_cast<BinaryOperator>(E)) {
    if (BO->getOpcode() != BO_EQ && BO->getOpcode() != BO_NE)
      return -1;

    const Expr *LHS = BO->getLHS()->IgnoreParenImpCasts();
    const Expr *RHS = BO->getRHS()->IgnoreParenImpCasts();

